// Paste this Office Script into Excel for the web in the Bond tenant.
// Power Automate supplies the source message and receives a Graph draft as JSON.

interface HtmlElement {
  tag: string;
  attributes: Record<string, string>;
  children: Array<HtmlElement | string>;
  parent?: HtmlElement;
}

interface IncomingAttachment {
  contentId?: string;
  contentType?: string;
  contentBytes?: string;
}

interface InlineImage {
  contentType: string;
  contentBytes: string;
}

interface DraftAttachment extends InlineImage {
  "@odata.type": string;
  contentId: string;
  name: string;
  isInline: boolean;
}

interface Article {
  title: string;
  href: string;
  summary: string;
  author: string;
  date: string;
  views: string;
  image?: InlineImage;
}

interface ArticleLink {
  href: string;
  destination: string;
}

interface TextField {
  text: string;
  kind: string;
}

const sharePointHost = "bonduni.sharepoint.com";
const newsHome = "https://bonduni.sharepoint.com/sites/News";
const careersUrl =
  "https://bonduni.sharepoint.com/sites/ShowcaseNews/SitePages/Careers-at-Bond(3).aspx";
const weekdays = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const months = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];

function main(
  workbook: ExcelScript.Workbook,
  sourceHtml: string,
  sourceAttachments: string,
  mailbox: string,
  brisbaneDate: string,
  careersWeekday: string = "Wednesday",
): string {
  // Excel requires a workbook argument. This script uses the workbook only to host execution.
  const to = mailbox.trim().toLowerCase();
  if (!/^[a-z0-9._%+-]+@bond\.edu\.au$/.test(to)) {
    throw new Error("Set mailbox to one Bond staff address.");
  }
  const date = new Date(brisbaneDate + "T00:00:00Z");
  if (
    !/^\d{4}-\d{2}-\d{2}$/.test(brisbaneDate) ||
    isNaN(date.getTime()) ||
    date.toISOString().slice(0, 10) !== brisbaneDate ||
    weekdays.indexOf(careersWeekday) === -1
  ) {
    throw new Error("Supply a Brisbane date in yyyy-MM-dd format and a valid Careers weekday.");
  }

  const elements = elementsIn(parseMailHtml(sourceHtml));
  if (
    !elements.some(
      (element) =>
        element.tag === "p" &&
        /^this (?:e-?mail|message) (?:is generated through|was generated by)\b.*\bMicrosoft 365\b/i.test(
          textOf(element),
        ),
    )
  ) {
    throw new Error("The message is missing the SharePoint digest footer.");
  }

  const images = readImages(sourceAttachments);
  const articles = readArticles(elements, images);
  if (!articles.length) throw new Error("No Bond SharePoint news articles were found.");

  const weekday = weekdays[date.getUTCDay()];
  let news = articles;
  if (weekday === careersWeekday) {
    const careersLink = canonicalPage(careersUrl);
    news = articles.filter(
      (article) => canonicalPage(bondLink(article.href).destination) !== careersLink,
    );
    news.push({
      title: "Careers at Bond",
      href: careersUrl,
      summary:
        "Looking for a new position? We are currently recruiting for a number of roles across campus.",
      author: "Annelize Oosthuizen",
      date: "25/01/2026",
      views: "",
      image: { contentType: "image/png", contentBytes: careersImageBase64 },
    });
  }

  const subject =
    "Bond Staff News | " +
    weekday +
    " " +
    date.getUTCDate() +
    " " +
    months[date.getUTCMonth()] +
    " " +
    date.getUTCFullYear();
  const siteLink = elements.find((element) => element.tag === "a" && isSiteLink(textOf(element)));
  const siteUrl = siteLink ? bondLink(siteLink.attributes.href || "").href || newsHome : newsHome;
  const attachments: DraftAttachment[] = [];
  const html = renderNews(news, siteUrl, subject, attachments);

  // The Outlook connection creates and sends this draft from its own mailbox.
  return JSON.stringify({
    subject,
    body: { contentType: "HTML", content: html },
    toRecipients: [{ emailAddress: { address: to } }],
    attachments,
  });
}

const entities: Record<string, string> = {
  amp: "&",
  lt: "<",
  gt: ">",
  quot: '"',
  apos: "'",
  nbsp: "\u00a0",
  ndash: "–",
  mdash: "—",
  lsquo: "‘",
  rsquo: "’",
  ldquo: "“",
  rdquo: "”",
  hellip: "…",
  copy: "©",
  bull: "•",
  reg: "®",
  shy: "\u00ad",
};

function decodeEntities(value: string): string {
  return value.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (whole, name: string) => {
    if (name[0] !== "#") return entities[name.toLowerCase()] || whole;
    const hexadecimal = name[1].toLowerCase() === "x";
    const codePoint = parseInt(name.slice(hexadecimal ? 2 : 1), hexadecimal ? 16 : 10);
    return codePoint > 0 && codePoint <= 0x10ffff ? String.fromCodePoint(codePoint) : whole;
  });
}

const voidTags = new Set([
  "area",
  "base",
  "br",
  "col",
  "embed",
  "hr",
  "img",
  "input",
  "link",
  "meta",
  "param",
  "source",
  "track",
  "wbr",
]);
const ignoredTags = new Set(["head", "script", "style", "template"]);

// The Office Script uses a small tree reader for SharePoint's email markup. It extracts text
// and attributes, and the original markup is kept out of the outgoing email.
function parseMailHtml(html: string): HtmlElement {
  const root: HtmlElement = { tag: "root", attributes: {}, children: [] };
  const stack: HtmlElement[] = [root];
  const tokens =
    /<!--[\s\S]*?-->|<![^>]*>|<\/?[a-z][a-z0-9:-]*(?=\s|\/?>)(?:"[^"]*"|'[^']*'|[^'"<>])*?>|[^<]+|</gi;
  let token = tokens.exec(html);
  while (token) {
    const raw = token[0];
    const tag = /^<(\/?)([a-z][a-z0-9:-]*)/i.exec(raw);
    if (tag) {
      const name = tag[2].toLowerCase();
      if (tag[1]) {
        for (let index = stack.length - 1; index > 0; index -= 1) {
          if (stack[index].tag === name) {
            stack.length = index;
            break;
          }
        }
      } else {
        const parent = stack[stack.length - 1];
        const node: HtmlElement = {
          tag: name,
          attributes: readAttributes(raw.slice(tag[0].length, -1)),
          children: [],
          parent,
        };
        parent.children.push(node);
        if (!voidTags.has(name) && !raw.endsWith("/>")) stack.push(node);
      }
    } else if (!raw.startsWith("<!")) {
      stack[stack.length - 1].children.push(decodeEntities(raw));
    }
    token = tokens.exec(html);
  }
  return root;
}

function readAttributes(raw: string): Record<string, string> {
  const fields: Record<string, string> = Object.create(null) as Record<string, string>;
  const pattern = /([^\s"'<>/=]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g;
  let match = pattern.exec(raw);
  while (match) {
    const name = match[1].toLowerCase();
    if (fields[name] === undefined)
      fields[name] = decodeEntities(match[2] ?? match[3] ?? match[4] ?? "");
    match = pattern.exec(raw);
  }
  return fields;
}

function elementsIn(root: HtmlElement): HtmlElement[] {
  const result: HtmlElement[] = [];
  const pending: HtmlElement[] = [root];
  for (let element = pending.pop(); element; element = pending.pop()) {
    if (ignoredTags.has(element.tag)) continue;
    result.push(element);
    for (let index = element.children.length - 1; index >= 0; index -= 1) {
      const child = element.children[index];
      if (typeof child !== "string") pending.push(child);
    }
  }
  return result;
}

function textOf(root: HtmlElement): string {
  const pending: Array<HtmlElement | string> = [root];
  const text: string[] = [];
  for (let value = pending.pop(); value !== undefined; value = pending.pop()) {
    if (typeof value === "string") text.push(value);
    else if (!ignoredTags.has(value.tag)) {
      for (let index = value.children.length - 1; index >= 0; index -= 1) {
        pending.push(value.children[index]);
      }
    }
  }
  return text.join("").replace(/\s+/g, " ").trim();
}

function httpsHost(href: string): string {
  return /^https:\/\/([a-z0-9.-]+)(?:[/?#][^\s<>"\\]*)?$/i.exec(href)?.[1].toLowerCase() || "";
}

function bondLink(value: string): ArticleLink {
  const href = value.trim();
  const host = httpsHost(href);
  if (host === sharePointHost) return { href, destination: href };

  // Microsoft Safe Links wraps the real URL. Keep the protected link if it targets Bond.
  if (host.endsWith(".safelinks.protection.outlook.com")) {
    const parameter = /[?&]url=([^&#]+)/i.exec(href)?.[1];
    if (parameter) {
      try {
        const destination = decodeURIComponent(parameter);
        if (httpsHost(destination) === sharePointHost) return { href, destination };
      } catch {
        // An invalid encoded destination cannot be classified as a Bond link.
      }
    }
  }
  return { href: "", destination: "" };
}

function canonicalPage(href: string): string {
  return href.split(/[?#]/)[0].replace(/%28/gi, "(").replace(/%29/gi, ")").toLowerCase();
}

function isSiteLink(text: string): boolean {
  return /^(?:go to (?:the )?site|view (?:the )?site|visit (?:the )?site|view all news and upcoming events)$/i.test(
    text,
  );
}

function closest(element: HtmlElement, tags: string[]): HtmlElement | undefined {
  for (let node: HtmlElement | undefined = element; node; node = node.parent) {
    if (tags.indexOf(node.tag) >= 0 || node.attributes.role === "listitem") return node;
  }
  return undefined;
}

function readArticles(elements: HtmlElement[], images: Map<string, InlineImage>): Article[] {
  const articles: Article[] = [];
  const seen = new Set<string>();
  for (const element of elements) {
    if (element.tag !== "a") continue;
    const { href, destination } = bondLink(element.attributes.href || "");
    const title = textOf(element);
    const page = canonicalPage(destination);
    if (
      !title ||
      !/\/(?:sitepages|pages)\/.+\.aspx$/i.test(page) ||
      seen.has(page) ||
      isSiteLink(title)
    ) {
      continue;
    }

    seen.add(page);
    const row = closest(element, ["tr", "article"]);
    const image = row ? findThumbnail(row, title, images) : undefined;
    articles.push({ title, href, image, ...readMetadata(articleFields(element)) });
  }
  return articles;
}

function articleFields(anchor: HtmlElement): TextField[] {
  const fields: TextField[] = [];
  const container = closest(anchor, ["td", "article"]);
  for (let node: HtmlElement | undefined = anchor; node && node !== container; node = node.parent) {
    const parent: HtmlElement | undefined = node.parent;
    if (!parent || ["body", "html", "root"].indexOf(parent.tag) >= 0) break;
    const siblings = parent.children.slice(parent.children.indexOf(node) + 1);
    for (const sibling of siblings) {
      if (typeof sibling !== "string") splitFields(sibling, fields);
    }
    if (!container && /^h[1-4]$/.test(node.tag)) break;
  }
  return fields;
}

function splitFields(element: HtmlElement, fields: TextField[]): void {
  if (!/^(?:div|p|td|span|time|section|ul|ol|li)$/.test(element.tag)) return;
  const text = textOf(element);
  if (!text) return;
  const children = element.children;
  const blocks = children.filter((child) => typeof child !== "string") as HtmlElement[];
  const ownText = children.some((child) => typeof child === "string" && Boolean(child.trim()));
  if (
    blocks.length > 1 &&
    !ownText &&
    blocks.every((block) => /^(?:div|p|time|li|span)$/.test(block.tag))
  ) {
    for (const block of blocks) splitFields(block, fields);
    return;
  }
  const kind =
    element.tag === "time"
      ? "date"
      : /author|byline/i.test(element.attributes.class || "")
        ? "author"
        : "";
  fields.push({ text, kind });
}

function readMetadata(fields: TextField[]): {
  summary: string;
  author: string;
  date: string;
  views: string;
} {
  const details = { summary: "", author: "", date: "", views: "" };
  const summary: string[] = [];
  const datePattern =
    /^(?:\d{4}-\d{1,2}-\d{1,2}|\d{1,2}[/.\-]\d{1,2}[/.\-]\d{2,4}|\d{1,2}\s+[\p{L}.]+\s+\d{4}|[\p{L}.]+\s+\d{1,2},?\s+\d{4})(?:,?\s+\d{1,2}:\d{2}.*)?$/u;
  for (const { text, kind } of fields) {
    if (!details.date && (kind === "date" || datePattern.test(text))) details.date = text;
    else if (!details.views && /^[\d.,\s]+\s+views?$/i.test(text)) details.views = text;
    else if (!details.author && (kind === "author" || /^by\s+/i.test(text)))
      details.author = text.replace(/^by\s+/i, "");
    else summary.push(text);
  }
  if (!details.author && details.date && summary.length === 2) details.author = summary.pop() || "";
  details.summary = summary.join("\n");
  return details;
}

function contentId(value: string): string {
  const id = value.trim().replace(/^cid:/i, "").replace(/^<|>$/g, "");
  try {
    return decodeURIComponent(id).toLowerCase();
  } catch {
    return id.toLowerCase();
  }
}

function readImages(payload: string): Map<string, InlineImage> {
  const attachments = JSON.parse(payload) as IncomingAttachment[];
  if (!Array.isArray(attachments)) throw new Error("Supply the Outlook attachments array.");
  const images = new Map<string, InlineImage>();
  for (const attachment of attachments) {
    const { contentId: id, contentType, contentBytes } = attachment;
    if (
      typeof id === "string" &&
      typeof contentType === "string" &&
      /^image\/(?:png|jpeg|gif|webp|bmp)$/i.test(contentType) &&
      typeof contentBytes === "string" &&
      /^[a-z0-9+/]+={0,2}$/i.test(contentBytes)
    ) {
      const key = contentId(id);
      if (!images.has(key)) images.set(key, { contentType, contentBytes });
    }
  }
  return images;
}

function findThumbnail(
  row: HtmlElement,
  title: string,
  images: Map<string, InlineImage>,
): InlineImage | undefined {
  const candidates = elementsIn(row).filter(
    (element) =>
      element.tag === "img" &&
      /^cid:/i.test(element.attributes.src || "") &&
      parseInt(element.attributes.width || "0", 10) !== 1,
  );
  const picture =
    candidates.find(
      (element) => (element.attributes.alt || "").trim().toLowerCase() === title.toLowerCase(),
    ) || candidates[0];
  return picture ? images.get(contentId(picture.attributes.src)) : undefined;
}

const htmlEscapes: Record<string, string> = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#39;",
};
const font = "'Segoe UI',Tahoma,Arial,sans-serif";
const title = "Staff News";
const introduction = "See the latest Showcase News items";
const footer = "View all news and upcoming events";
const divider =
  '<tr><td colspan="2" style="border-top:1px solid #d6d6d6;font-size:0;line-height:1px;height:1px;">&nbsp;</td></tr>';

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => htmlEscapes[character]);
}

function renderLink(href: string, label: string, style: string): string {
  return `<a href="${escapeHtml(href)}" style="${style}">${escapeHtml(label)}</a>`;
}

function addInlineImage(image: InlineImage, attachments: DraftAttachment[], label: string): string {
  const id = label + "-" + (attachments.length + 1) + "@digest-bot.local";
  attachments.push({
    "@odata.type": "#microsoft.graph.fileAttachment",
    name: label + "." + image.contentType.split("/")[1],
    contentId: id,
    isInline: true,
    contentType: image.contentType,
    contentBytes: image.contentBytes,
  });
  return "cid:" + id;
}

function renderArticle(article: Article, attachments: DraftAttachment[]): string {
  const articleTitle = renderLink(article.href, article.title, "color:#333;text-decoration:none;");
  const imageSource = article.image ? addInlineImage(article.image, attachments, "article") : "";
  const image = imageSource
    ? `<img src="${escapeHtml(imageSource)}" alt="${escapeHtml(article.title)}" width="210" style="display:block;width:210px;max-width:100%;height:auto;border:0;">`
    : "";
  const summary = escapeHtml(article.summary).replace(/\r?\n/g, "<br>");
  return `
    <tr>
      ${image ? `<td class="article-image" width="220" valign="top" style="width:220px;padding:20px 0;">${image}</td>` : ""}
      <td class="article-copy${image ? " with-image" : ""}" ${image ? "" : 'colspan="2"'} valign="top" style="padding:20px 0 20px ${image ? "20px" : "0"};overflow-wrap:anywhere;">
        <h2 style="margin:0 0 10px;font-size:17px;line-height:20px;font-weight:400;">${articleTitle}</h2>
        ${summary ? `<p style="margin:0 0 12px;font-size:14px;line-height:1.4;color:#666;">${summary}</p>` : ""}
        ${article.author ? `<p style="margin:0 0 3px;font-size:12px;line-height:13.5px;color:#231f20;">${escapeHtml(article.author)}</p>` : ""}
        ${article.date ? `<p style="margin:0;font-size:11px;line-height:13.5px;color:#767676;">${escapeHtml(article.date)}</p>` : ""}
        ${article.views ? `<p style="margin:10px 0 0;font-size:10px;line-height:1.4;color:#a6a6a6;">${escapeHtml(article.views)}</p>` : ""}
      </td>
    </tr>`;
}

// The Staff News table layout mirrors the existing formatter. This runtime generates HTML
// and Exchange inline attachments together in place of a MIME response.
function renderNews(
  articles: Article[],
  siteUrl: string,
  subject: string,
  attachments: DraftAttachment[],
): string {
  const logoSource = addInlineImage(
    { contentType: "image/png", contentBytes: bondLogoBase64 },
    attachments,
    "bond-logo",
  );
  const headerLogo = `<img src="${escapeHtml(logoSource)}" alt="Bond University" width="214" height="82" style="display:block;width:214px;max-width:100%;height:auto;margin:0 auto;border:0;">`;
  const rows = articles.map((article) => renderArticle(article, attachments));
  const html = `<!doctype html>
<html lang="en-AU">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">

<title>${escapeHtml(subject)}</title>
<style>
  @media only screen and (max-width: 460px) {
    .digest-outer { padding: 16px 10px !important; }
    .digest-articles { table-layout: auto !important; }
    .digest-articles colgroup { display: none !important; }
    .article-image, .article-copy { display: block !important; width: 100% !important; box-sizing: border-box; }
    .article-image { padding-bottom: 0 !important; }
    .article-copy.with-image { padding: 14px 0 20px !important; }
  }
</style>
</head>
<body style="margin:0;background-color:#fff;color:#222;font-family:${font};" dir="ltr">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:#fff;font-family:${font};">
    <tr><td align="center" class="digest-outer" style="padding:22px 0 0;">
      <!--[if mso]><table role="presentation" width="600" cellpadding="0" cellspacing="0"><tr><td><![endif]-->
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
        style="max-width:600px;border:1px solid #dedede;border-collapse:collapse;margin:0 auto;">
        <tr><td align="center" style="padding:20px 20px 36px;border-bottom:1px solid #c8c8c8;background-color:#fff;">
          ${headerLogo}
          <h1 style="margin:30px 0 10px;font-size:24px;line-height:32px;font-weight:600;color:#222;">${title}</h1>
          <p style="margin:0;font-size:17px;line-height:1.35;color:#95989a;">${introduction}</p>
        </td></tr>
        <tr><td style="padding:0 20px;background-color:#f8f8f8;">
          <table role="presentation" class="digest-articles" width="100%" cellpadding="0" cellspacing="0" border="0"
            style="table-layout:fixed;border-collapse:collapse;">
            <colgroup><col width="220" style="width:220px;"><col></colgroup>${rows.join(divider)}</table>
        </td></tr>
        <tr><td align="center" style="padding:30px;border-top:1px solid #dedede;background-color:#fff;font-size:14px;line-height:1.4;">
          ${renderLink(siteUrl, footer, "color:#0000ee;text-decoration:underline;")}
        </td></tr>
      </table>
      <!--[if mso]></td></tr></table><![endif]-->
    </td></tr>
  </table>
</body>
</html>`;
  return html;
}

// The two PNGs below come from dist/assets and server/assets. Embedding them keeps the
// Office Script self-contained and avoids a file lookup on each flow run.
const bondLogoBase64 =
  "";
const careersImageBase64 =
  "";
